(() => {
 'use strict';
 const timing={slide:240,digitStart:120,stagger:32,digitDuration:360,surfaceDelay:30,surfaceDuration:260};
 const smooth=(a,b,x)=>{const t=Math.max(0,Math.min(1,(x-a)/(b-a)));return t*t*(3-2*t);};
 const format=n=>n.toLocaleString('en-US');
 const feet='<svg viewBox="0 0 64 70" fill="currentColor" aria-hidden="true"><g transform="rotate(-15 19 46)"><ellipse cx="19" cy="47" rx="9" ry="15"/><ellipse cx="9" cy="28" rx="2.5" ry="3.3"/><ellipse cx="14" cy="23" rx="3" ry="4"/><ellipse cx="21" cy="21" rx="3.6" ry="4.8"/><ellipse cx="28" cy="25" rx="3.6" ry="5.3"/></g><g transform="rotate(16 44 28)"><ellipse cx="44" cy="31" rx="9" ry="15"/><ellipse cx="34" cy="10" rx="3.9" ry="5.4"/><ellipse cx="42" cy="7" rx="3.4" ry="4.7"/><ellipse cx="49" cy="10" rx="2.9" ry="4"/><ellipse cx="55" cy="15" rx="2.3" ry="3.3"/></g></svg>';
 function surface(steps,baseline){const ratio=baseline>0?steps/baseline:0,bloom=smooth(.90,1.04,ratio),fog=1-smooth(.92,1,ratio);return {cover:Math.max(0,(1-ratio)*100),fog,line:.34*fog,rim:(.25+.45*bloom)/.766,glow:.30+.22*bloom};}
 function mount(root,initial,{compact=false,showData=true,countId}={}){
  let data=initial,frame=0,generation=0,animations=[],current;
  root.classList.add('steps-sun');root.dataset.compact=String(compact);
  root.innerHTML='<div class="ss-glow"></div><div class="ss-disc"></div><div class="ss-frost"></div><div class="ss-memory"></div><div class="ss-line"></div>'+(showData?'<div class="ss-copy">'+feet+'<strong class="ss-count"></strong><p class="ss-comparison"><span class="ss-direction" aria-hidden="true"></span><span></span></p></div>':'');
  const count=root.querySelector('.ss-count');if(countId&&count)count.id=countId;
  function apply(s){current={...s};for(const [name,value]of Object.entries(s))root.style.setProperty('--ss-'+name,value+(name==='cover'?'%':name==='rim'?'cqw':''));}
  function paint(){const ratio=data.baseline>0?data.steps/data.baseline:0;root.dataset.state=ratio>=1?'above':'below';apply(surface(data.steps,data.baseline));root.setAttribute('role','img');root.setAttribute('aria-label',`${format(data.steps)} steps, compared with ${format(data.baseline)} typical ${data.name} steps by ${data.referenceTime}.`);if(count){count.classList.remove('ss-entering');count.textContent=format(data.steps);count.removeAttribute('aria-label');root.querySelector('.ss-comparison>span:last-child').textContent=ratio===1?`Typical ${data.name}`:`${ratio>1?'Above':'Below'} typical ${data.name}`;}}
  function cancel(){generation++;cancelAnimationFrame(frame);animations.forEach(a=>a.cancel());animations=[];paint();}
  function digits(delay=timing.digitStart){if(!count)return;const text=format(data.steps);count.replaceChildren();count.classList.add('ss-entering');count.setAttribute('aria-label',text);[...text].forEach((char,i)=>{const glyph=document.createElement('span');glyph.className='ss-digit';glyph.textContent=char;glyph.setAttribute('aria-hidden','true');count.append(glyph);animations.push(glyph.animate([{transform:'translateY(-.65em) scale(.72)',opacity:0,offset:0,easing:'cubic-bezier(.2,.6,.3,1)'},{transform:'translateY(.025em) scale(1.1)',opacity:1,offset:.68,easing:'cubic-bezier(.3,0,.4,1)'},{transform:'translateY(0) scale(1)',opacity:1,offset:1}],{duration:timing.digitDuration,delay:delay+i*timing.stagger,easing:'linear',fill:'both'}));});}
  function update(next,{animate=true}={}){const from=current;cancel();data=next;paint();const target={...current};if(!animate||matchMedia('(prefers-reduced-motion: reduce)').matches)return;const token=generation,start=performance.now();apply(from);function tick(now){if(token!==generation)return;const t=Math.min(1,(now-start)/timing.surfaceDuration),s={};for(const k of Object.keys(target))s[k]=from[k]+(target[k]-from[k])*t;apply(s);if(t<1)frame=requestAnimationFrame(tick);}frame=requestAnimationFrame(tick);}
  function open(page){cancel();if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const token=generation,target={...current},start=performance.now();apply({cover:78,fog:1,line:.3,rim:.25/.766,glow:.3});if(page)animations.push(page.animate([{transform:'translateX(100%)',offset:0},{transform:'translateX(94%)',offset:.12},{transform:'translateX(50%)',offset:.5},{transform:'translateX(0)',offset:1}],{duration:timing.slide,easing:'linear'}));digits();const caption=root.querySelector('.ss-comparison');if(caption)animations.push(caption.animate([{opacity:0},{opacity:1}],{duration:135,delay:265,fill:'both',easing:'linear'}));const finish=Math.max(660,timing.digitStart+(format(data.steps).length-1)*timing.stagger+timing.digitDuration+10);function tick(now){if(token!==generation)return;const t=Math.max(0,Math.min(1,(now-start-timing.surfaceDelay)/timing.surfaceDuration));apply({cover:78+(target.cover-78)*t,fog:1+(target.fog-1)*t,line:.3+(target.line-.3)*t,rim:(.25/.766)+(target.rim-.25/.766)*t,glow:.3+(target.glow-.3)*t});if(t<1||now-start<finish)frame=requestAnimationFrame(tick);else cancel();}frame=requestAnimationFrame(tick);}
  paint();return {update,open,cancel};
 }
 window.FitLensSun={mount,surface,timing};
 const home=document.querySelector('#home-steps-sun');if(home){const data=window.FitLensStepsData.days[window.FitLensStepsData.today];mount(home,data,{compact:true});const link=home.closest('a');link.setAttribute('aria-label',`${format(data.steps)} steps, ${data.steps>=data.baseline?'above':'below'} your typical ${data.name}. View details`);link.querySelector('.fl-typical').textContent=data.steps>=data.baseline?'Above your usual':'Below your usual';}
})();
